// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        bound(amount, 1, 10 ether);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.addToBalance{value: amount}();

        assertTrue(c.getBalance(actor) == amount);
    }
}
